+import { ExportedIndex } from "../core/index-db";
+
+export interface RepositoryIndex {
+  repoName: string;
+  url: string;
+  index: ExportedIndex | null;
+  error?: string;
+}
+
+export interface FederatedQuery {
+  searchTrailer?: string;
+  searchRecordId?: string;
+  searchPath?: string;
+}
+
+export interface QueryResult {
+  repo: string;
+  recordId: string;
+  sha: string;
+  path: string;
+  trailer: string;
+}
+
+const DEFAULT_BRANCH = "main";
+const INDEX_RELEASE_TAG = "commitlore-index";
+
+export const fetchRepositoryIndex = async (repoUrl: string): Promise<ExportedIndex | null> => {
+  const match = repoUrl.match(/github\.com[:/]([^/]+)\/([^/.]+)/);
+  if (!match) throw new Error(`Invalid GitHub URL: ${repoUrl}`);
+
+  const [, owner, repo] = match;
+  const apiUrl = `https://api.github.com/repos/${owner}/${repo}`;
+
+  try {
+    // Try to fetch from latest release
+    const releaseRes = await fetch(`${apiUrl}/releases/latest`);
+    if (releaseRes.ok) {
+      const release = await releaseRes.json() as { assets?: Array<{ name: string; browser_download_url: string }> };
+      const asset = release.assets?.find(a => a.name === "commitlore-index.json");
+      if (asset) {
+        const indexRes = await fetch(asset.browser_download_url);
+        if (indexRes.ok) return indexRes.json() as ExportedIndex;
+      }
+    }
+
+    // Fallback: fetch raw from default branch (for repos without releases)
+    const fallbackUrl = `https://raw.githubusercontent.com/${owner}/${repo}/${DEFAULT_BRANCH}/commitlore-index.json`;
+    const fallbackRes = await fetch(fallbackUrl);
+    if (fallbackRes.ok) return fallbackRes.json() as ExportedIndex;
+
+    return null;
+  } catch (err) {
+    return null;
+  }
+};
+
+export const fetchAllIndices = async (
+  repoUrls: string[],
+  options?: { parallelism?: number; timeout?: number }
+): Promise<RepositoryIndex[]> => {
+  const parallelism = options?.parallelism ?? 5;
+  const timeout = options?.timeout ?? 30000;
+
+  const results: RepositoryIndex[] = [];
+  const queue = [...repoUrls];
+
+  const worker = async () => {
+    while (queue.length > 0) {
+      const url = queue.shift();
+      if (!url) break;
+
+      const repoName = url.split("/").slice(-1)[0].replace(".git", "");
+      try {
+        const controller = new AbortController();
+        const timer = setTimeout(() => controller.abort(), timeout);
+
+        const index = await Promise.race([
+          fetchRepositoryIndex(url),
+          new Promise<null>(() => {}), // Never resolves, waits for timeout
+        ]);
+
+        clearTimeout(timer);
+        results.push({ repoName, url, index: index || null });
+      } catch (err) {
+        results.push({
+          repoName,
+          url,
+          index: null,
+          error: err instanceof Error ? err.message : String(err),
+        });
+      }
+    }
+  };
+
+  // Run workers in parallel
+  const workers = Array.from({ length: parallelism }, () => worker());
+  await Promise.all(workers);
+
+  return results;
+};
+
+export const queryFederatedIndices = (
+  indices: RepositoryIndex[],
+  query: FederatedQuery
+): QueryResult[] => {
+  const results: QueryResult[] = [];
+
+  for (const repo of indices) {
+    if (!repo.index) continue;
+
+    for (const record of repo.index.records) {
+      const matches =
+        (!query.searchRecordId || record.recordId.includes(query.searchRecordId)) &&
+        (!query.searchTrailer || record.trailer.toLowerCase().includes(query.searchTrailer.toLowerCase())) &&
+        (!query.searchPath || record.path.includes(query.searchPath));
+
+      if (matches) {
+        results.push({
+          repo: repo.repoName,
+          recordId: record.recordId,
+          sha: record.sha,
+          path: record.path,
+          trailer: record.trailer,
+        });
+      }
+    }
+  }
+
+  return results;
+};
