+#!/usr/bin/env node
+
+import fs from "fs";
+import path from "path";
+import { fetchAllIndices, queryFederatedIndices, FederatedQuery } from "./federation/index-fetcher";
+
+interface OrgConfig {
+  repositories: string[];
+}
+
+const loadOrgConfig = (configPath: string): OrgConfig => {
+  const content = fs.readFileSync(configPath, "utf-8");
+  return JSON.parse(content);
+};
+
+const formatResults = (results: ReturnType<typeof queryFederatedIndices>): string => {
+  if (results.length === 0) {
+    return "No matching records found.";
+  }
+
+  const grouped = new Map<string, (typeof results)>();
+  for (const result of results) {
+    if (!grouped.has(result.repo)) grouped.set(result.repo, []);
+    grouped.get(result.repo)!.push(result);
+  }
+
+  let output = `Found ${results.length} record(s) across ${grouped.size} repo(s):\n\n`;
+  for (const [repo, repoResults] of grouped) {
+    output += `${repo}:\n`;
+    for (const r of repoResults) {
+      output += `  [${r.recordId}] ${r.sha.slice(0, 7)}\n`;
+      output += `    ${r.trailer}\n`;
+      output += `    (${r.path})\n\n`;
+    }
+  }
+  return output;
+};
+
+const main = async () => {
+  const args = process.argv.slice(2);
+
+  if (args.length === 0) {
+    console.error("Usage: org-query [--config <path>] [--trailer <keyword>] [--record-id <id>] [--path <pattern>]");
+    console.error("Example: org-query --config orgs/mycompany.json --trailer authentication");
+    process.exit(1);
+  }
+
+  let configPath = ".commitlore/org-config.json";
+  const query: FederatedQuery = {};
+
+  for (let i = 0; i < args.length; i++) {
+    const arg = args[i];
+    if (arg === "--config") configPath = args[++i];
+    else if (arg === "--trailer") query.searchTrailer = args[++i];
+    else if (arg === "--record-id") query.searchRecordId = args[++i];
+    else if (arg === "--path") query.searchPath = args[++i];
+  }
+
+  try {
+    const config = loadOrgConfig(configPath);
+    console.log(`Querying ${config.repositories.length} repositories...\n`);
+
+    const indices = await fetchAllIndices(config.repositories, { parallelism: 5 });
+
+    const successful = indices.filter(r => r.index).length;
+    const failed = indices.filter(r => !r.index).length;
+    console.log(`Loaded ${successful} index(es), ${failed} failed/unavailable.\n`);
+
+    const results = queryFederatedIndices(indices, query);
+    console.log(formatResults(results));
+  } catch (err) {
+    console.error("Error:", err instanceof Error ? err.message : err);
+    process.exit(1);
+  }
+};
+
+if (require.main === module) {
+  main();
+}
