+      color: #1a1a1a;
+    }
+    .result-group {
+      margin-bottom: 20px;
+      padding: 12px;
+      background: #f9f9f9;
+      border-left: 3px solid #0066cc;
+      border-radius: 4px;
+    }
+    .result-group-title {
+      font-weight: 600;
+      margin-bottom: 8px;
+      color: #1a1a1a;
+    }
+    .record {
+      margin: 8px 0;
+      padding: 8px;
+      background: white;
+      border-radius: 3px;
+      font-size: 0.85em;
+    }
+    .record-id {
+      font-family: monospace;
+      font-weight: 600;
+      color: #0066cc;
+      margin-bottom: 4px;
+    }
+    .record-sha {
+      color: #666;
+      font-family: monospace;
+      font-size: 0.8em;
+    }
+    .record-trailer {
+      margin: 6px 0;
+      line-height: 1.4;
+      color: #333;
+    }
+    .record-path {
+      color: #999;
+      font-size: 0.8em;
+      font-family: monospace;
+    }
+    .empty-state {
+      text-align: center;
+      padding: 40px 20px;
+      color: #999;
+    }
+  </style>
+</head>
+<body>
+  <div class="header">
+    <h1>CommitLore Org-wide Query</h1>
+    <p class="subtitle">Search decisions across all repositories</p>
+  </div>
+
+  <div class="container">
+    <div class="config-section">
+      <h2>1. Repository Configuration</h2>
+      <p>Paste your org config JSON (list of repository URLs):</p>
+      <textarea id="orgConfig" placeholder='[
+  "https://github.com/org/repo1",
+  "https://github.com/org/repo2"
+]'></textarea>
+      <button onclick="loadSampleConfig()">Load Sample</button>
+    </div>
+
+    <div class="query-section">
+      <h2>2. Search Query</h2>
+      <div class="form-group">
+        <label for="trailer">Search in trailer text:</label>
+        <input type="text" id="trailer" placeholder="e.g., authentication, security">
+      </div>
+      <div class="form-group">
+        <label for="recordId">Search in record ID:</label>
+        <input type="text" id="recordId" placeholder="e.g., r-abc123">
+      </div>
+      <div class="form-group">
+        <label for="path">Search in path:</label>
+        <input type="text" id="path" placeholder="e.g., src/auth">
+      </div>
+
+      <div class="button-group">
+        <button class="primary" onclick="executeQuery()" id="queryBtn">Search Across Repos</button>
+        <button onclick="clearResults()">Clear</button>
+      </div>
+    </div>
+
+    <div id="status"></div>
+    <div id="results" class="results" style="display:none;"></div>
+  </div>
+
+  <script>
+    const loadSampleConfig = () => {
+      const sample = [
+        "https://github.com/org/backend",
+        "https://github.com/org/frontend",
+        "https://github.com/org/infrastructure",
+        "https://github.com/org/mobile"
+      ];
+      document.getElementById("orgConfig").value = JSON.stringify(sample, null, 2);
+    };
+
+    const showStatus = (message, type = "loading") => {
+      const el = document.getElementById("status");
+      el.className = `status ${type}`;
+      el.textContent = message;
+    };
+
+    const clearResults = () => {
+      document.getElementById("status").textContent = "";
+      document.getElementById("results").style.display = "none";
+    };
+
+    const fetchRepositoryIndex = async (repoUrl) => {
+      const match = repoUrl.match(/github\.com[:/]([^/]+)\/([^/.]+)/);
+      if (!match) throw new Error(`Invalid GitHub URL: ${repoUrl}`);
+
+      const [, owner, repo] = match;
+      const apiUrl = `https://api.github.com/repos/${owner}/${repo}`;
+
+      try {
+        // Try to fetch from latest release
+        const releaseRes = await fetch(`${apiUrl}/releases/latest`, {
+          headers: { Accept: "application/vnd.github.v3+json" }
+        });
+        if (releaseRes.ok) {
+          const release = await releaseRes.json();
+          if (release.assets) {
+            const asset = release.assets.find(a => a.name === "commitlore-index.json");
+            if (asset) {
+              const indexRes = await fetch(asset.browser_download_url);
+              if (indexRes.ok) return await indexRes.json();
+            }
+          }
+        }
+
+        // Fallback: fetch raw from main branch
+        const fallbackUrl = `https://raw.githubusercontent.com/${owner}/${repo}/main/commitlore-index.json`;
+        const fallbackRes = await fetch(fallbackUrl);
+        if (fallbackRes.ok) return await fallbackRes.json();
+
+        return null;
+      } catch (err) {
+        return null;
+      }
+    };
+
+    const executeQuery = async () => {
+      const configText = document.getElementById("orgConfig").value.trim();
+      if (!configText) {
+        showStatus("Please paste repository configuration", "error");
+        return;
+      }
+
+      const query = {
+        searchTrailer: document.getElementById("trailer").value.trim() || undefined,
+        searchRecordId: document.getElementById("recordId").value.trim() || undefined,
+        searchPath: document.getElementById("path").value.trim() || undefined
+      };
+
+      if (!query.searchTrailer && !query.searchRecordId && !query.searchPath) {
+        showStatus("Please enter at least one search term", "error");
+        return;
+      }
+
+      const btn = document.getElementById("queryBtn");
+      btn.disabled = true;
+
+      try {
+        let repos;
+        try {
+          repos = JSON.parse(configText);
+        } catch (e) {
+          showStatus("Invalid JSON configuration", "error");
+          btn.disabled = false;
+          return;
+        }
+
+        showStatus(`Querying ${repos.length} repositories...`, "loading");
+
+        const indices = await Promise.all(
+          repos.map(async (url) => {
+            try {
+              const index = await fetchRepositoryIndex(url);
+              const repoName = url.split("/").pop().replace(".git", "");
+              return { repoName, url, index, error: null };
+            } catch (err) {
+              const repoName = url.split("/").pop().replace(".git", "");
+              return { repoName, url, index: null, error: err.message };
+            }
+          })
+        );
+
+        const successful = indices.filter(r => r.index).length;
+        const failed = indices.filter(r => !r.index).length;
+
+        showStatus(`Loaded ${successful} indices (${failed} unavailable)`, "success");
+
+        // Query
+        const results = [];
+        for (const repo of indices) {
+          if (!repo.index) continue;
+          for (const record of repo.index.records) {
+            const matches =
+              (!query.searchRecordId || record.recordId.includes(query.searchRecordId)) &&
+              (!query.searchTrailer || record.trailer.toLowerCase().includes(query.searchTrailer.toLowerCase())) &&
+              (!query.searchPath || record.path.includes(query.searchPath));
+
+            if (matches) {
+              results.push({
+                repo: repo.repoName,
+                recordId: record.recordId,
+                sha: record.sha,
+                path: record.path,
+                trailer: record.trailer
+              });
+            }
+          }
+        }
+
+        displayResults(results);
+      } catch (err) {
+        showStatus(`Error: ${err.message}`, "error");
+      } finally {
+        btn.disabled = false;
+      }
+    };
+
+    const displayResults = (results) => {
+      const resultsEl = document.getElementById("results");
+      if (results.length === 0) {
+        resultsEl.innerHTML = '<div class="empty-state">No matching records found</div>';
+        resultsEl.style.display = "block";
+        return;
+      }
+
+      const grouped = new Map();
+      for (const result of results) {
+        if (!grouped.has(result.repo)) grouped.set(result.repo, []);
+        grouped.get(result.repo).push(result);
+      }
+
+      let html = `<h2>Found ${results.length} record(s)</h2>`;
+      for (const [repo, repoResults] of grouped) {
+        html += `<div class="result-group">
+          <div class="result-group-title">${repo} (${repoResults.length})</div>`;
+        for (const r of repoResults) {
+          html += `<div class="record">
+            <div class="record-id">${r.recordId}</div>
+            <div class="record-sha">${r.sha.slice(0, 7)}</div>
+            <div class="record-trailer">${r.trailer}</div>
+            <div class="record-path">${r.path}</div>
+          </div>`;
+        }
+        html += '</div>';
+      }
+      resultsEl.innerHTML = html;
+      resultsEl.style.display = "block";
+    };
+
+    // Load sample on page load
+    window.addEventListener("load", () => {
+      loadSampleConfig();
+    });
+  </script>
+</body>
+</html>
